import { describe, expect, it } from "vitest";
import { scryptSync } from "node:crypto";
import { hashPassword, verifyPassword } from "./password.js";

// Fixtures generated by the previous native argon2 0.44.0 implementation.
const existing =
  "$argon2id$v=19$m=19456,t=2,p=1$MDEyMzQ1Njc4OWFiY2RlZg$MTqsk1JTq6d4GIgVb+Q/uEIy7lmruC3AWzkG8w06GrI";
const unicode =
  "$argon2id$v=19$m=65536,t=3,p=4$ZmVkY2JhOTg3NjU0MzIxMA$Gwl7DKvvDMkiaCIHdP9qOrsgSE9JNDdybByhXCFj9hI";

describe("portable password hashing", () => {
  it("accepts existing native Argon2id hashes and rejects wrong passwords", async () => {
    expect(await verifyPassword("Existing-Password-42", existing)).toBe(true);
    expect(await verifyPassword("wrong-password", existing)).toBe(false);
  });
  it("accepts native Unicode hashes with different cost and parallelism", async () => {
    expect(
      await verifyPassword(
        "Compat-\u{1F512}-\u092A\u093E\u0938\u0935\u0930\u094D\u0921",
        unicode,
      ),
    ).toBe(true);
  });
  it("retains the current Argon2id parameters and uses fresh salts", async () => {
    const [first, second] = await Promise.all([
      hashPassword("New-Password-42"),
      hashPassword("New-Password-42"),
    ]);
    expect(first).toMatch(/^\$argon2id\$v=19\$m=19456,t=2,p=1\$/);
    expect(first).not.toBe(second);
    expect(await verifyPassword("New-Password-42", first)).toBe(true);
    expect(await verifyPassword("wrong-password", first)).toBe(false);
  });
  it("preserves legacy scrypt authentication", async () => {
    const digest = scryptSync("Legacy-Password-42", "legacy-salt", 64).toString(
      "hex",
    );
    const stored = `scrypt:legacy-salt:${digest}`;
    expect(await verifyPassword("Legacy-Password-42", stored)).toBe(true);
    expect(await verifyPassword("wrong-password", stored)).toBe(false);
  });
  it("rejects malformed or unsupported stored hashes", async () => {
    for (const stored of [
      "",
      "$argon2id$invalid",
      existing.replace("m=19456", "m=0"),
      "scrypt::",
      "other:salt:digest",
    ]) {
      expect(await verifyPassword("Existing-Password-42", stored)).toBe(false);
    }
  });
  it("handles concurrent password operations independently", async () => {
    const results = await Promise.all(
      Array.from({ length: 6 }, (_, i) =>
        verifyPassword(
          i % 2 ? "wrong-password" : "Existing-Password-42",
          existing,
        ),
      ),
    );
    expect(results).toEqual([true, false, true, false, true, false]);
  });
  it("bounds queued hashing work and recovers after overload", async () => {
    const results = await Promise.allSettled(
      Array.from({ length: 40 }, () =>
        verifyPassword("Existing-Password-42", existing),
      ),
    );
    const denied = results.filter((result) => result.status === "rejected");
    expect(denied.length).toBeGreaterThan(0);
    for (const result of denied)
      if (result.status === "rejected")
        expect(result.reason.code).toBe("PASSWORD_HASH_BUSY");
    expect(await verifyPassword("Existing-Password-42", existing)).toBe(true);
  });
});
